@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h2>Warehouse Dashboard</h2>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-5 fw-bold">@GetWarehouseName()</p>
                <p class="text-muted small">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold @(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted small">Items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">Active — every 10s</span>
                </p>
                <button class="btn btn-sm btn-outline-primary mt-2" @onclick="RefreshManually">
                    Refresh Now
                </button>
            </div>
        </div>
    </div>
</div>

<div class="alert alert-info mt-4">
    <strong>How this works:</strong> This page activates polling on the <code>InventoryAlertService</code>.
    Every 10 seconds, new low-stock data is fetched for the selected warehouse.
    Both this dashboard card and the sidebar badge update simultaneously via the shared event.
    Switching warehouses in the top bar triggers an immediate refresh.
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    private async Task HandleAlertChanged() => await InvokeAsync(StateHasChanged);

    private async Task RefreshManually() => await AlertService.RefreshNowAsync();

    private string GetWarehouseName()
    {
        var match = Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return match.Name ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
    }
}

